use super::{Clipboard, Content};
use anyhow::{Result, ensure};
use objc2::rc::{Retained, autoreleasepool};
use objc2_app_kit::{
    NSBitmapImageFileType, NSBitmapImageRep, NSPasteboard, NSPasteboardAccessBehavior,
    NSPasteboardTypeString,
};
use objc2_foundation::{NSArray, NSData, NSDictionary, NSString};

/// Types that mark content as not for syncing, per nspasteboard.org. Password
/// managers set these.
const SKIPPED_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];
/// Copying a file in Finder puts its icon on the pasteboard, which isn't
/// something to sync as a picture.
const FILE_URL: &str = "public.file-url";
const PNG: &str = "public.png";
const TIFF: &str = "public.tiff";

/// `name` selects a private pasteboard, which lets tests avoid the real clipboard.
pub struct MacClipboard {
    name: Option<String>,
}

impl MacClipboard {
    pub fn new(name: Option<String>) -> Self {
        Self { name }
    }

    fn board(&self) -> Retained<NSPasteboard> {
        match &self.name {
            Some(name) => NSPasteboard::pasteboardWithName(&NSString::from_str(name)),
            None => NSPasteboard::generalPasteboard(),
        }
    }
}

fn data(board: &NSPasteboard, kind: &str) -> Option<Vec<u8>> {
    board
        .dataForType(&NSString::from_str(kind))
        .map(|data| data.to_vec())
}

fn tiff_to_png(tiff: &[u8]) -> Option<Vec<u8>> {
    let rep = NSBitmapImageRep::imageRepWithData(&NSData::with_bytes(tiff))?;
    let png = unsafe {
        rep.representationUsingType_properties(NSBitmapImageFileType::PNG, &NSDictionary::new())
    }?;
    Some(png.to_vec())
}

impl Clipboard for MacClipboard {
    fn change_token(&self) -> u64 {
        autoreleasepool(|_| self.board().changeCount() as u64)
    }

    fn read(&self) -> Result<Option<Content>> {
        Ok(autoreleasepool(|_| {
            let board = self.board();
            let types: Vec<String> = board
                .types()
                .map(|types: Retained<NSArray<NSString>>| {
                    types.iter().map(|t| t.to_string()).collect()
                })
                .unwrap_or_default();
            if types.iter().any(|t| SKIPPED_TYPES.contains(&t.as_str())) {
                return None;
            }
            if let Some(text) = board.stringForType(unsafe { NSPasteboardTypeString }) {
                return Some(Content::Text(text.to_string()));
            }
            if types.iter().any(|t| t == FILE_URL) {
                return None;
            }
            if types.iter().any(|t| t == PNG) {
                return data(&board, PNG).map(Content::Image);
            }
            if types.iter().any(|t| t == TIFF) {
                return data(&board, TIFF)
                    .and_then(|tiff| tiff_to_png(&tiff))
                    .map(Content::Image);
            }
            None
        }))
    }

    fn write(&self, content: &Content) -> Result<()> {
        let wrote = autoreleasepool(|_| {
            let board = self.board();
            board.clearContents();
            match content {
                Content::Text(text) => board.setString_forType(&NSString::from_str(text), unsafe {
                    NSPasteboardTypeString
                }),
                Content::Image(png) => {
                    board.setData_forType(Some(&NSData::with_bytes(png)), &NSString::from_str(PNG))
                }
            }
        });
        ensure!(wrote, "the pasteboard refused the write");
        Ok(())
    }

    fn startup_note(&self) -> Option<String> {
        if self.name.is_some() {
            return None;
        }
        let behavior = autoreleasepool(|_| self.board().accessBehavior());
        const SETTINGS: &str = "System Settings > Privacy & Security > Paste from Other Apps";
        if behavior == NSPasteboardAccessBehavior::AlwaysDeny {
            Some(format!(
                "macOS is denying clipboard access, so copies here won't sync. Allow it in {SETTINGS}."
            ))
        } else if behavior == NSPasteboardAccessBehavior::AlwaysAllow {
            None
        } else {
            Some(format!(
                "macOS will ask before each clipboard read. Choose Always Allow, or change it in {SETTINGS}."
            ))
        }
    }
}
